using Dapper; using InovaGed.Application.Common.Database; using InovaGed.Application.Continuity;
namespace InovaGed.Infrastructure.Continuity;
public sealed class PortabilityManifestService(IDbConnectionFactory db):IPortabilityManifestService { public async Task<PortabilityManifest> BuildAsync(Guid exportId,CancellationToken ct){await using var c=await db.OpenAsync(ct);var row=await c.QuerySingleOrDefaultAsync<(Guid? TenantId,string Scope,string Status,string? CorrelationId)>(new CommandDefinition("select tenant_id TenantId,scope,status,correlation_id CorrelationId from ged.portability_export where id=@exportId",new{exportId},cancellationToken:ct));if(row==default)return new("1.0",exportId,null,"UNKNOWN",DateTime.UtcNow,"NOT_FOUND",Guid.NewGuid().ToString("N"),[]);var files=(await c.QueryAsync<PortabilityManifestFile>(new CommandDefinition("select relative_path Path,size_bytes SizeBytes,sha256 Sha256 from ged.portability_artifact where export_id=@exportId order by relative_path",new{exportId},cancellationToken:ct))).AsList();return new("1.0",exportId,row.TenantId,row.Scope,DateTime.UtcNow,row.Status,row.CorrelationId??Guid.NewGuid().ToString("N"),files);} }
